import {
  Mesh,
  MeshBasicNodeMaterial,
  PlaneGeometry,
  Euler,
  Vector3,
  TextureLoader
} from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // --- desconstruct config ---
  const { scenePosition, sceneRotation, sceneScale, assets, behaviorSpec, cinematicPrimitives } = config;
  const { imageUrl } = assets;

  // --- geometry & material ---
  // aspect from atlas region (512x320) → 1.6; pick height 0.8 scene units
  const w = 1.28;
  const h = 0.8;
  const geometry = new PlaneGeometry(w, h);
  const texture = ctx.textureLoader.load(imageUrl);
  // assume atlas region is the whole texture (no offset/repeat needed)
  const material = new MeshBasicNodeMaterial({ map: texture });
  const mesh = new Mesh(geometry, material);

  // --- placement ---
  mesh.position.copy(new Vector3(
    scenePosition?.x ?? 0,
    scenePosition?.y ?? 0,
    scenePosition?.z ?? 0
  ));
  if (sceneRotation) {
    mesh.rotation.set(
      sceneRotation.x ?? 0,
      sceneRotation.y ?? 0,
      sceneRotation.z ?? 0
    );
  } else {
    mesh.rotation.copy(new Euler(0, 0, 0));
  }
  if (sceneScale) {
    mesh.scale.copy(new Vector3(
      sceneScale.x ?? 1,
      sceneScale.y ?? 1,
      sceneScale.z ?? 1
    ));
  }

  // --- cinematic primitives ---
  if (cinematicPrimitives) {
    for (const prim of cinematicPrimitives) {
      const apply = ctx.primitives[prim.name];
      if (apply) {
        apply(mesh, prim.params || {});
      }
    }
  }

  // --- interaction handling ---
  const timelines = [];

  // hover: subtle rise-in
  const baseY = mesh.position.y;
  const liftAmount = 0.15;

  mesh.userData.handlers = {
    pointerenter: () => {
      const tl = gsap.to(mesh.position, {
        y: baseY + liftAmount,
        duration: 0.5,
        ease: 'power3.out',
        overwrite: 'auto'
      });
      timelines.push(tl);
    },
    pointerleave: () => {
      const tl = gsap.to(mesh.position, {
        y: baseY,
        duration: 0.5,
        ease: 'power3.out',
        overwrite: 'auto'
      });
      timelines.push(tl);
    },
    click: (e) => {
      // press-down animation
      const tl = gsap.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        yoyo: true,
        repeat: 1,
        onComplete: () => {
          // emit event
          if (ctx.emit) {
            ctx.emit('hub-pricing.select', { mesh, config });
          }
        }
      });
      timelines.push(tl);
    }
  };

  // --- cleanup ---
  mesh.userData.cleanup = () => {
    // kill all GSAP timelines
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    // dispose three.js resources
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
  };

  return mesh;
}
